def validate(version: int = 0xDC4) -> dict:
    out = {}
    for arch in ("client", "server"):
        raw, rows = load_rows(arch)
        ok = bad = 0
        first = None
        lens = set()
        for r in rows:
            b = raw[r["body_start"]:r["body_start"] + r["body_len"]]
            lens.add(r["body_len"])
