                             "consumed": s["pos"], "gaps": s["gaps"][:3]}
        out[arch] = {"rows": len(rows), "closed": ok, "open": bad,
                     "distinct_len": len(lens), "first_open": first}
    return {"version": hex(version), "result": out}


